// ── LANGUAGE CONTEXT + PROVIDER ──────────────────────────────────────────────
const LanguageContext = createContext({ lang: "en", setLang: () => {}, t: (k) => k });

function detectInitialLang() {
  try {
    const params = new URLSearchParams(window.location.search);
    const urlLang = params.get("lang");
    if (urlLang && TRANSLATIONS[urlLang]) return urlLang;
    const saved = localStorage.getItem("dg_lang");
    if (saved && TRANSLATIONS[saved]) return saved;
    const nav = (navigator.language || "en").slice(0, 2);
    if (TRANSLATIONS[nav]) return nav;
  } catch (e) { /* ignore */ }
  return "en";
}

function LanguageProvider({ children }) {
  const [lang, setLangState] = useState(detectInitialLang());
  const setLang = (l) => {
    setLangState(l);
    try { localStorage.setItem("dg_lang", l); } catch (e) { /* ignore */ }
  };
  // t(key): returns the string for the current language, falling back to English, then the key itself.
  const t = (key) =>
    (TRANSLATIONS[lang] && TRANSLATIONS[lang][key]) ??
    (TRANSLATIONS.en && TRANSLATIONS.en[key]) ??
    key;
  return (
    <LanguageContext.Provider value={{ lang, setLang, t }}>
      {children}
    </LanguageContext.Provider>
  );
}

// Hook used inside components: const { t, lang, setLang } = useT();
function useT() {
  return useContext(LanguageContext);
}

// Translate a CATEGORY label for DISPLAY only. Matching logic keeps the English label.
function tCategory(t, englishLabel) {
  return t("cat_" + englishLabel);
}

// ── LANGUAGE SWITCHER (drop into nav bar and/or landing page) ────────────────
function appSummary(app, lang) {
  if (lang === "de" && app.summaryDe) return app.summaryDe;
  if (lang === "fr" && app.summaryFr) return app.summaryFr;
  return app.summary;
}

function LanguageSwitcher() {
  const { lang, setLang } = useT();
  const [open, setOpen] = useState(false);
  const langs = [
    { code: "en", label: "English", short: "EN" },
    { code: "fr", label: "Français", short: "FR" },
    { code: "de", label: "Deutsch", short: "DE" },
  ];
  const current = langs.find((l) => l.code === lang) || langs[0];
  return (
    <div style={{ position: "relative", flexShrink: 0 }}>
      <button
        onClick={() => setOpen((v) => !v)}
        style={{
          display: "flex",
          alignItems: "center",
          gap: "5px",
          background: "rgba(255,255,255,0.05)",
          border: "1px solid rgba(255,255,255,0.12)",
          color: "rgba(255,255,255,0.7)",
          borderRadius: "10px",
          padding: "5px 9px",
          fontSize: "11px",
          fontWeight: "700",
          cursor: "pointer",
          fontFamily: "'DM Mono', monospace",
          letterSpacing: "0.5px",
          transition: "all 0.15s",
        }}
      >
        <span style={{ fontSize: "13px" }}>🌐</span>
        <span>{current.short}</span>
        <span style={{ fontSize: "8px", display: "inline-block", transform: open ? "rotate(180deg)" : "rotate(0deg)", transition: "transform 0.2s" }}>▼</span>
      </button>
      {open && (
        <>
          <div style={{ position: "fixed", inset: 0, zIndex: 199 }} onClick={() => setOpen(false)} />
          <div style={{ position: "absolute", top: "calc(100% + 6px)", right: 0, background: "#0f0f20", border: "1px solid rgba(255,255,255,0.12)", borderRadius: "12px", zIndex: 200, overflow: "hidden", boxShadow: "0 12px 40px rgba(0,0,0,0.6)", minWidth: "130px" }}>
            {langs.map((l, i) => {
              const active = lang === l.code;
              return (
                <button
                  key={l.code}
                  onClick={() => { setLang(l.code); setOpen(false); }}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                    gap: "10px",
                    width: "100%",
                    padding: "11px 14px",
                    background: active ? "rgba(239,83,80,0.12)" : "transparent",
                    border: "none",
                    borderBottom: i < langs.length - 1 ? "1px solid rgba(255,255,255,0.05)" : "none",
                    color: active ? "#ff8a80" : "rgba(255,255,255,0.7)",
                    fontSize: "13px",
                    fontWeight: active ? "700" : "400",
                    cursor: "pointer",
                    textAlign: "left",
                    fontFamily: "'DM Mono', monospace",
                  }}
                >
                  <span>{l.label}</span>
                  <span style={{ fontSize: "10px", opacity: 0.6 }}>{l.short}</span>
                </button>
              );
            })}
          </div>
        </>
      )}
    </div>
  );
}


